export const NUMBER_WORDS = {
  en: ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'],
  de: ['null', 'eins', 'zwei', 'drei', 'vier', 'fünf', 'sechs', 'sieben', 'acht', 'neun'],
  fr: ['zéro', 'un', 'deux', 'trois', 'quatre', 'cinq', 'six', 'sept', 'huit', 'neuf'],
  es: ['cero', 'uno', 'dos', 'tres', 'cuatro', 'cinco', 'seis', 'siete', 'ocho', 'nueve'],
  ja: ['ぜろ', 'いち', 'に', 'さん', 'よん', 'ご', 'ろく', 'なな', 'はち', 'きゅう'],
};

// more translations, kept in their own files by area (reading and recording, notebook, Help, the Idea Room)
Object.assign(T, READER_T, NOTEBOOK_T, HELP_T, IDEAS_T);

export function translate(lang, s, vars) {
  const row = T[s];
  let out = (row && (lang !== 'en' ? row[lang] : row.en)) || s; // (a row may also give its own English words)
  if (vars) for (const k of Object.keys(vars)) out = out.split(`{${k}}`).join(String(vars[k]));
  return out;
}

// the language, shared with every screen
export const LangContext = createContext({ lang: 'en', setLang: () => {} });
export const useLang = () => useContext(LangContext).lang;
export function useT() {
  const { lang } = useContext(LangContext);
  return (s, vars) => translate(lang, s, vars);
}
